llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C45"],
      "claim": "A comparative bioavailability study in myasthenia gravis patients reported pyridostigmine oral bioavailability of 7.6%, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Neostigmine, a closely related quaternary ammonium dimethylcarbamate, had absolute oral bioavailability of only 2.0 ± 0.33% in fasted myasthenic patients, supporting poor absorption of permanently charged carbamates.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Bambuterol, a neutral bis-dimethylcarbamate, has about 10% oral bioavailability, below the threshold, reinforcing that carbamate-containing small molecules can have low oral systemic availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Rivastigmine, a tertiary-amine carbamate analogue, reached 71.7% oral bioavailability at 6 mg, but it lacks the permanent quaternary charge of the query, so this high value does not transfer to the pyridinium compound.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is pyridostigmine, a quaternary pyridinium dimethylcarbamate. Direct comparative data give pyridostigmine oral bioavailability ~7.6%, and the closely related quaternary neostigmine is ~2%; both are below 20%. High bioavailability in tertiary-amine rivastigmine does not transfer because the permanent positive charge is the dominant absorption barrier. Therefore predict low.",
  "evidence_gaps": [
    "No dedicated absolute bioavailability card for pyridostigmine itself was provided; the 7.6% value appears within a neostigmine comparison record.",
    "Salt form and counterion effects on absorption are not specified.",
    "Most human data are from myasthenia gravis patients rather than healthy subjects, which may affect generalizability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

